6	/**
7	 * SDK Session Adapter
8	 *
9	 * Thin conversion layer between the `@anthropic-ai/claude-agent-sdk` session APIs
10	 * and our internal types (`IClaudeCodeSessionInfo`, `IClaudeCodeSession`, `StoredMessage`).
11	 *
12	 * The SDK provides:
13	 * - `listSessions()` / `getSessionInfo()` → `SDKSessionInfo`
14	 * - `getSessionMessages()` → `SessionMessage[]`
15	 *
16	 * This adapter converts those into the shapes consumed by `chatHistoryBuilder.ts`
17	 * and `claudeChatSessionContentProvider.ts` without any JSONL parsing.
18	 */
19	
20	import type { SDKSessionInfo, SessionMessage } from '@anthropic-ai/claude-agent-sdk';
21	import {
22		AssistantMessageContent,
23		IClaudeCodeSession,
24		IClaudeCodeSessionInfo,
25		ISubagentSession,
26		StoredMessage,
27		UserMessageContent,
28		vAssistantMessageContent,
29		vUserMessageContent,
30	} from './claudeSessionSchema';
31	
32	// #region Label Helpers
33	
34	/**
35	 * Strips `<system-reminder>` tags and their content from a string.
36	 * The SDK includes raw system-reminder blocks in `summary` and `firstPrompt` fields.
37	 */
38	function stripSystemReminders(text: string): string {
39		return text.replace(/<system-reminder>[\s\S]*?<\/system-reminder>\s*/g, '').trim();
40	}
41	
42	/**
43	 * Computes a clean display label from SDK session info.
44	 * Priority: customTitle > stripped summary > stripped firstPrompt > fallback.
45	 */
46	function computeSessionLabel(info: SDKSessionInfo): string {
47		if (info.customTitle) {
48			return info.customTitle;
49		}
50	
51		const summary = info.summary ? stripSystemReminders(info.summary) : '';
52		if (summary) {
53			return truncateLabel(summary);
54		}
55	
56		const firstPrompt = info.firstPrompt ? stripSystemReminders(info.firstPrompt) : '';
57		if (firstPrompt) {
58			return truncateLabel(firstPrompt);
59		}
60	
61		return 'Claude Session';
62	}
63	
64	const MAX_LABEL_LENGTH = 50;
65	
66	function truncateLabel(text: string): string {
67		const singleLine = text.replace(/\s+/g, ' ');
68		if (singleLine.length <= MAX_LABEL_LENGTH) {
69			return singleLine;
70		}
71		return singleLine.slice(0, MAX_LABEL_LENGTH) + '…';
72	}
73	
74	// #endregion
75	
76	// #region SDKSessionInfo → IClaudeCodeSessionInfo
77	
78	/**
79	 * Converts an `SDKSessionInfo` (from `listSessions` / `getSessionInfo`) into
80	 * the lightweight `IClaudeCodeSessionInfo` used by the session list UI.
81	 */
82	export function sdkSessionInfoToSessionInfo(
83		info: SDKSessionInfo,
84		folderName?: string,
85	): IClaudeCodeSessionInfo {
86		return {
87			id: info.sessionId,
88			label: computeSessionLabel(info),
89			created: info.createdAt ?? info.lastModified,
90			lastRequestEnded: info.lastModified,
91			folderName,
92			cwd: info.cwd,
93			gitBranch: info.gitBranch,
94		};
95	}
96	
97	// #endregion
98	
99	// #region SessionMessage → StoredMessage
100	
101	/**
102	 * A map from user message UUID to the agentId of the subagent spawned by
103	 * a Task tool result in that message. Extracted from raw JSONL `toolUseResult.agentId`
104	 * during subagent discovery (since the SDK's `getSessionMessages` strips this field).
105	 */
106	export type SubagentCorrelationMap = ReadonlyMap<string, string>;
107	
108	/**
109	 * Converts an array of `SessionMessage` (from `getSessionMessages`) into
110	 * `StoredMessage[]` compatible with `chatHistoryBuilder.ts`.
111	 *
112	 * Uses existing validators (`vUserMessageContent`, `vAssistantMessageContent`)
113	 * to narrow the `message: unknown` field into typed content.
114	 *
115	 * Messages that fail validation are silently skipped — this matches the parser
116	 * behavior of ignoring malformed JSONL entries.
117	 *
118	 * @param messages SDK session messages
119	 * @param subagentCorrelation Optional map from user message UUID → subagent agentId,
120	 *   used to set `toolUseResultAgentId` for subagent tool nesting in the chat UI.
121	 */
122	export function sdkSessionMessagesToStoredMessages(
123		messages: readonly SessionMessage[],
124		subagentCorrelation?: SubagentCorrelationMap,
125	): StoredMessage[] {
126		const result: StoredMessage[] = [];
127	
128		for (const msg of messages) {
129			const stored = sdkSessionMessageToStoredMessage(msg, subagentCorrelation);
130			if (stored) {
131				result.push(stored);
132			}
133		}
134	
135		return result;
136	}
137	
138	function sdkSessionMessageToStoredMessage(
139		msg: SessionMessage,
140		subagentCorrelation?: SubagentCorrelationMap,
141	): StoredMessage | undefined {
142		if (msg.type === 'user') {
143			const validated = vUserMessageContent.validate(msg.message);
144			if (validated.error) {
145				return undefined;
146			}
147			return {
148				uuid: msg.uuid,
149				sessionId: msg.session_id,
150				timestamp: new Date(0),
151				parentUuid: null,
152				type: 'user',
153				message: validated.content as UserMessageContent,
154				toolUseResultAgentId: subagentCorrelation?.get(msg.uuid),
155			};
156		}
157	
158		if (msg.type === 'assistant') {
159			const validated = vAssistantMessageContent.validate(msg.message);
160			if (validated.error) {
161				return undefined;
162			}
163			return {
164				uuid: msg.uuid,
165				sessionId: msg.session_id,
166				timestamp: new Date(0),
167				parentUuid: null,
168				type: 'assistant',
169				message: validated.content as AssistantMessageContent,
170			};
171		}
172	
173		return undefined;
174	}
175	
176	// #endregion
177	
178	// #region Subagent Session Building
179	
180	/**
181	 * Converts SDK `SessionMessage[]` (from `getSubagentMessages`) into an
182	 * `ISubagentSession` for display in the chat history.
183	 *
184	 * @param agentId The subagent identifier
185	 * @param messages SDK subagent messages
186	 * @returns A subagent session, or null if no valid messages
187	 */
188	export function sdkSubagentMessagesToSubagentSession(
189		agentId: string,
190		messages: readonly SessionMessage[],
191	): ISubagentSession | null {
192		const storedMessages = sdkSessionMessagesToStoredMessages(messages);
193		if (storedMessages.length === 0) {
194			return null;
195		}
196	
197		return {
198			agentId,
199			messages: storedMessages,
200			timestamp: storedMessages[storedMessages.length - 1].timestamp,
201		};
202	}
203	
204	// #endregion
205	
206	// #region Full Session Assembly
207	
208	/**
209	 * Assembles a full `IClaudeCodeSession` from SDK data and separately-loaded subagents.
210	 *
211	 * @param info Session metadata from the SDK
212	 * @param messages Session transcript from the SDK
213	 * @param subagents Subagent sessions loaded from raw JSONL (SDK doesn't expose these)
214	 * @param subagentCorrelation Map from user message UUID → subagent agentId for nesting
215	 * @param folderName Optional workspace folder name for badge display
216	 */
217	export function buildClaudeCodeSession(
218		info: SDKSessionInfo,
219		messages: readonly SessionMessage[],
220		subagents: readonly ISubagentSession[],
221		subagentCorrelation?: SubagentCorrelationMap,
222		folderName?: string,
223	): IClaudeCodeSession {
224		const sessionInfo = sdkSessionInfoToSessionInfo(info, folderName);
225		const storedMessages = sdkSessionMessagesToStoredMessages(messages, subagentCorrelation);
226	
227		return {
228			...sessionInfo,
229			messages: storedMessages,
230			subagents,
231		};
232	}
233	
234	// #endregion
