107	/**
108	 * Checks if a text block contains a system-reminder tag.
109	 * System-reminders are stored in separate content blocks and should not be rendered.
110	 */
111	function isSystemReminderBlock(text: string): boolean {
112		return text.includes('<system-reminder>');
113	}
114	
115	/**
116	 * Strips <system-reminder> tags and their content from a string.
117	 * Used for backwards compatibility with legacy sessions where system-reminders
118	 * were concatenated with user text in a single string.
119	 *
120	 * TODO: Remove this function after a few releases (added in 0.38.x) once legacy
121	 * sessions with concatenated system-reminders are no longer common.
122	 */
123	function stripSystemReminders(text: string): string {
124		return text.replace(/<system-reminder>[\s\S]*?<\/system-reminder>\s*/g, '');
125	}
126	
127	/**
128	 * Extracts visible text content from a user message, filtering out system reminders.
129	 */
130	function extractTextContent(content: string | ContentBlock[]): string {
131		if (typeof content === 'string') {
132			// TODO: Remove this branch when stripSystemReminders is removed (legacy compat)
133			return stripSystemReminders(content);
134		}
135	
136		// For array content (new format), filter out entire blocks that are system-reminders
137		return content
138			.filter(isTextBlock)
139			.filter(block => !isSystemReminderBlock(block.text))
140			.map(block => block.text)
141			.join('');
142	}
