110	 *
111	 * @param messages SDK session messages
112	 */
113	export function sdkSessionMessagesToStoredMessages(
114		messages: readonly SessionMessage[],
115	): StoredMessage[] {
116		const result: StoredMessage[] = [];
117	
118		for (const msg of messages) {
119			const stored = sdkSessionMessageToStoredMessage(msg);
120			if (stored) {
121				result.push(stored);
122			}
123		}
124	
125		return result;
126	}
